class Solution {
    public int minMoves(int[] nums,int limit){
        int[] difference=new int[2*limit+2];
        for(int left=0,right=nums.length-1;left<right;left++,right--){
            int low=Math.min(nums[left],nums[right]),high=Math.max(nums[left],nums[right]),sum=low+high;
            difference[2]+=2;
            difference[low+1]--;
            difference[sum]--;
            difference[sum+1]++;
            difference[high+limit+1]++;
        }
        int moves=0,answer=Integer.MAX_VALUE;
        for(int sum=2;sum<=2*limit;sum++){
            moves+=difference[sum];
            answer=Math.min(answer,moves);
        }
        return answer;
    }
}

